function extract(raw, memory, info) {
  raw = raw || {}; memory = memory || {}; info = info || {};
  var TICK = 16, G = 0.25, JUMP = -4.6, OFF = 12, PAD = 2, BIG = 1e9, DEAD = -1e9;
  var H = 80, H_ANY = 60, CG = 190, S_UP = 1, S_DN = 1.2, SOFT = 10, SOFTPAD = 20, DISC = 0.05, AIM = 16, BUDGET = 30000, BUDGET_ANY = 20000;
  var M_IN = 0.5, M_OUT = 0.5, WMIN = 17 - 4 * Math.sin(1);
  var i, j, k, n;
  function isNum(a) { return typeof a === 'number' && isFinite(a); }
  function num(a, d) { return isNum(a) ? a : d; }
  // running estimate that rises fast and falls slowly: about the 85th percentile of its samples
  function upper(e, x) { return isNum(e) ? e + (x > e ? 0.3 : 0.05) * (x - e) : x; }
