  function boxOf(v) {
    var r = Math.abs(Math.min(v / 10 * 90, 90)), a = r * Math.PI / 180;
    var bh = 34 * Math.sin(a) + 24 * Math.cos(a);
    return [bh / 2, (24 + bh) / 4, 17 - 4 * Math.sin(r / 90)];
  }
  var screen = num(raw.screen, -1);
  var ground = num(raw.ground, num(raw.height, 420));
  var bird = raw.bird || {};
  // the bird never moves sideways: average its centre to remove the rounding of its box
  var cx = num(bird.x, 59) + num(bird.w, 36) / 2, cxm = memory.cxN >= 5 ? memory.cxS / memory.cxN : null;
  if (screen === 1 && isNum(bird.x) && isNum(bird.w) && (cxm === null || Math.abs(cx - cxm) < 3)) {
    memory.cxS = (memory.cxS || 0) + cx; memory.cxN = (memory.cxN || 0) + 1;
    if (cxm !== null) cx = memory.cxS / memory.cxN;
  }
  var BL = cx - 17, BR = cx + 17;
  var top = num(raw.top, num(bird.y, 200));
  var v0 = num(raw.velocity, 0);
  var lag = Math.max(0, num(info.lagMs, 0));
  var now = isNum(info.nowMs) ? info.nowMs : (isNum(memory.lastNow) ? memory.lastNow + TICK : 0);
  var live = screen === 1 && memory.lastScreen === 1 && isNum(memory.lastNow) && now > memory.lastNow;
  // no game frame ran since the last frame shown (the game's 16.7 ms timer skips about one 16 ms tick in 25)
  var skip = screen === 1 && memory.lastScreen === 1 && v0 === memory.lastV && top === memory.lastTop;

  // game frame length: whole gravity steps (+0.25 each) over flap-free intervals, counting intervals with no frame
  if (live && isNum(memory.lastV) && now - memory.lastNow <= 400) {
    var frf = (v0 - memory.lastV) / G, fr = Math.round(frf);
    if (memory.lastV > -3.5 && v0 > -4 && fr >= 0 && Math.abs(frf - fr) < 0.2) {
      memory.fT = (memory.fT || 0) + now - memory.lastNow; memory.fN = (memory.fN || 0) + fr;
    }
  }
  var FRAME = memory.fN >= 30 ? Math.min(18, Math.max(15, memory.fT / memory.fN)) : 1000 / 60;
  // time to the next frame shown, measured apart after frames the engine was asked on (it flaps there and the next frame
  // waits for it) and after frames it was not asked on (askWhen false: the next frame follows after one short step)
  if (live) {
    var dtD = Math.min(150, Math.max(4, now - memory.lastNow));
    if (memory.lastAsk) memory.cA = upper(memory.cA, dtD); else memory.cU = upper(memory.cU, dtD);
  }
  var DECA = isNum(memory.cA) ? memory.cA : Math.max(TICK, lag);
  var DECU = isNum(memory.cU) ? memory.cU : DECA;

  var pipes = [], odd = [], list = Array.isArray(raw.pipes) ? raw.pipes : [];
  for (i = 0; i < list.length; i++) {
    var p = list[i];
    if (!p || !isNum(p.x)) continue;
    if (isNum(p.gapTop) && isNum(p.gapBottom)) pipes.push({ x: p.x, w: num(p.w, 52), gt: p.gapTop, gb: p.gapBottom });
    else odd.push({ kind: 'pipe', x: p.x, y: num(p.y, 0), w: num(p.w, 52), h: num(p.h, ground) });
  }
  var known = { screen: 1, bird: 1, top: 1, velocity: 1, ground: 1, width: 1, height: 1, pipes: 1 };
  for (var key in raw) {
    if (known[key] || /cloud|star|score|digit|decor|sky|back|text|label|title|medal|best/i.test(key)) continue;
    var val = raw[key], arr = Array.isArray(val) ? val : (val && typeof val === 'object' ? [val] : []);
    for (i = 0; i < arr.length && i < 20; i++) {
      var o = arr[i];
      if (o && typeof o === 'object' && isNum(o.x)) odd.push({ kind: key, x: o.x, y: num(o.y, 0), w: num(o.w, num(o.width, 0)), h: num(o.h, num(o.height, 0)) });
    }
  }
  var unk = null, unkN = 0;
  for (i = 0; i < odd.length; i++) {
    if (odd[i].x + odd[i].w < BL) continue;
    unkN++;
    if (!unk || odd[i].x < unk.x) unk = odd[i];
  }
  pipes.sort(function (a, b) { return a.x - b.x; });
  // a pipe stays in play a little past the bird's tail: the game drops it only a frame after the bird has cleared it
  var ahead = [];
  for (i = 0; i < pipes.length; i++) if (pipes[i].x + pipes[i].w + 4 >= BL) ahead.push(pipes[i]);
  var lead = ahead[0], sec = ahead[1];

  // pipe speed (px/ms), measured on the leading pipe over the time since it became the lead. Consecutive pipes can share
  // a gap: the lead counts as the same pipe only while it keeps moving left by a plausible step from the last frame
  var speed = isNum(memory.speed) ? memory.speed : 1000 / 7500;
  if (screen === 1 && lead) {
    var tr = memory.track;
    if (tr && tr.gt === lead.gt && tr.gb === lead.gb && isNum(tr.lx) && now >= tr.lt && lead.x <= tr.lx + 1 && tr.lx - lead.x <= 0.6 * (now - tr.lt) + 3) {
      if (now - tr.t >= 200) { var sp = (tr.x - lead.x) / (now - tr.t); if (sp > 0.03 && sp < 0.6) speed = sp; }
      memory.track = { gt: tr.gt, gb: tr.gb, x: tr.x, t: tr.t, lx: lead.x, lt: now };
    } else memory.track = { gt: lead.gt, gb: lead.gb, x: lead.x, t: now, lx: lead.x, lt: now };
  } else if (screen !== 1) memory.track = null;
  memory.speed = speed;

  // lookahead: memoised max-min search with alpha-beta bounds over the frames the flaps can land on
  var hT = [], hB = [], nI = [], nO = [], sT = [], sB = [], tg = [], FA = [], EA = [], WA = [], FB = [], EB = [], WB = [];
  var memoV = {}, memoT = {}, steps = 0, budget = BUDGET, enough = CG, hz = H, jit = false, gapA = 1, slot = [];
  function clr(j, cy, e, fh, w) {
    var c = ground - cy - fh;
    if (c <= 0) return DEAD;
    var bt = cy - e, bb = cy + e, x;
    // the pipe is tested once the hitbox (half width w) reaches past its left edge, until a frame after it is past its right edge
    if (hT[j] > -BIG && w > nI[j] && w >= nO[j]) {
      x = bt - hT[j]; if (x <= 0) return DEAD; if (x < c) c = x;
      x = hB[j] - bb; if (x <= 0) return DEAD; if (x < c) c = x;
    }
    x = Math.min(bt - sT[j], sB[j] - bb) + SOFTPAD;
    if (x < c) c = x;
    c += DISC * j;
    return c > CG ? CG : (c < -150 ? -150 : c);
  }
  // best worst-case clearance from frame f + 1 on, exact inside (lo, hi), otherwise only a bound on that side
  // (flap: a flap landed after frame f; else the bird coasts from now). The next flap can land after a slot frame c,
  // at the earliest one engine time after the last flap. With jit it lands after c or after c + 1 and both must work,
  // except with luck, where the better of the two counts
  function run(f, y, flap, lo, hi, luck) {
    var E = flap ? EB : EA, Fh = flap ? FB : FA, W = flap ? WB : WA, base = flap ? JUMP : v0;
    var Y = [], M = [], cc = [], cs = [], ord = [], m = BIG, last = hz, minC = flap ? f + Math.max(1, gapA - 1) : f + 1;
    var jj, nn, vv, c, a, r, x, fl, best;
    for (jj = f + 1; jj <= hz; jj++) {
      nn = flap ? jj - f : jj; vv = base + G * nn; y += vv; steps++;
      c = clr(jj, y + OFF, E[nn], Fh[nn], W[nn]);
      if (c === DEAD) { last = jj - 1; break; }
      if (c < m) m = c;
      if (y + OFF - E[nn] <= 0) y = 0;
      Y[jj] = y; M[jj] = m;
      if (slot[jj] === true && jj >= minC && jj < hz) { cc.push(jj); cs.push(Math.abs(y + OFF - tg[jj + 1] - AIM) + (vv < 0 ? 60 : 0)); }
    }
    best = last < hz ? last + 1 - 300 : (m >= BIG ? CG : m);
    if (best >= hi || best >= enough) return best;
    for (a = 0; a < cc.length; a++) ord.push(a);
    ord.sort(function (p1, p2) { return cs[p1] - cs[p2]; });
    for (a = 0; a < ord.length && steps <= budget; a++) {
      c = cc[ord[a]]; fl = best > lo ? best : lo;
      if (jit && !luck) {
        // the worse of the two landing frames counts
        if (c + 1 > last || M[c + 1] <= fl) continue;
        r = V(c, Y[c], fl, M[c + 1]); if (r > M[c + 1]) r = M[c + 1];
        if (r > fl) { x = V(c + 1, Y[c + 1], fl, r); if (x < r) r = x; }
      } else {
        // the flap lands after frame c (with luck: after c + 1 instead when that is better)
        if (M[c] <= fl) continue;
        r = V(c, Y[c], fl, M[c]); if (r > M[c]) r = M[c];
        if (luck && c + 1 <= last && r < M[c + 1]) {
          x = V(c + 1, Y[c + 1], r > fl ? r : fl, M[c + 1]); if (x > M[c + 1]) x = M[c + 1]; if (x > r) r = x;
        }
      }
      if (r <= fl) continue;
      best = r;
      if (best >= hi || best >= enough) break;
    }
    return best;
  }
  function V(f, y, lo, hi) {
    var mk = f * 4096 + Math.round(y) + 1024, t = memoT[mk], r;
    if (t !== undefined) {
      r = memoV[mk];
      if (t === 0 || (t < 0 && r <= lo) || (t > 0 && r >= hi)) return r;
    }
    r = run(f, y, true, lo, hi, false);
    if (r <= lo) { memoV[mk] = lo; memoT[mk] = -1; }
    else { memoV[mk] = r; memoT[mk] = r >= hi ? 1 : 0; }
    return r;
  }
  // frames 1..f0 run before this decision's flap can land, whatever is chosen now; returns
  // [flap: worse landing, flap: better landing, wait, wait with the next flap on its better frame, clearance over frames 1..f0]
  function roots(f0) {
    var y = top, mPre = BIG, c, q, aE, aL, wR, wL, y1;
    for (q = 1; q <= f0; q++) {
      y += v0 + G * q;
      c = clr(q, y + OFF, EA[q], FA[q], WA[q]);
      if (c === DEAD) return [q - 300, q - 300, q - 300, q - 300, BIG];
      if (c < mPre) mPre = c;
      if (y + OFF - EA[q] <= 0) y = 0;
    }
    steps = 0; aE = V(f0, y, -BIG, BIG); aL = aE;
    if (jit) {
      // the flap may land a frame later: that frame still runs without it
      q = f0 + 1; y1 = y + v0 + G * q;
      c = clr(q, y1 + OFF, EA[q], FA[q], WA[q]);
      if (c === DEAD) aL = q - 300;
      else {
        if (y1 + OFF - EA[q] <= 0) y1 = 0;
        steps = 0; aL = Math.min(c, V(q, y1, -BIG, BIG));
      }
    }
    steps = 0; wR = run(f0, y, false, -BIG, BIG, false); wL = wR;
    if (jit && wR < -200) { steps = 0; wL = Math.max(wR, run(f0, y, false, -BIG, BIG, true)); }
    return [Math.min(aE, aL), Math.max(aE, aL), wR, wL, mPre];
  }
  // one number per choice: sure (-150..190), a gamble on the landing frame (-199..-152), or a crash (-300 + its frame)
  function score(rob, luc) {
    if (rob > -200) return rob;
    if (luc > -200) return -199 + (Math.min(36, luc) + 150) / 4;
    return luc;
  }

  var sF = 0, sW = 0, pF = 0, pW = 0, dieF = false, dieW = false;
  if (screen === 1) {
    try {
      var nA = Math.min(ahead.length, 4);
      for (j = 0; j <= H; j++) {
        // the game reads pipe positions from the last 16 ms page frame: entry is tested with the pipe half a frame on,
        // removal with the pipe where it was one frame earlier (two after a skipped tick)
        var tIn = (j - 0.5) * FRAME, tOut = ((j === 1 && skip) ? -2 : j - 2) * FRAME;
        var ht = -BIG, hb = BIG, ni = BIG, no = BIG, st = -BIG, sb = BIG, first = true;
        for (i = 0; i < nA; i++) {
          var q = ahead[i], eOut = q.x - speed * tOut + q.w - PAD + M_OUT, eIn = q.x - speed * tIn - PAD - M_IN;
          if (eOut < BL) continue;
          if (first) {
            first = false;
            if (eIn < BR) { ht = q.gt; hb = q.gb; ni = eIn - cx; no = cx - eOut; if (ni < WMIN) continue; }
          }
          var d = Math.max(0, eIn - BR);
          st = Math.max(st, q.gt - S_UP * d - SOFT);
          sb = Math.min(sb, q.gb + S_DN * d + SOFT);
        }
        hT.push(ht); hB.push(hb); nI.push(ni); nO.push(no); sT.push(st); sB.push(sb);
        tg.push(ht > -BIG ? (ht + hb) / 2 : (st > -BIG ? (Math.max(st, 40) + Math.min(sb, ground - 40)) / 2 : ground - 200));
      }
