        var ba = boxOf(v0 + G * n), bf = boxOf(JUMP + G * n);
        FA.push(ba[0]); EA.push(ba[1]); WA.push(ba[2]); FB.push(bf[0]); EB.push(bf[1]); WB.push(bf[2]);
      }
      // a flap lands lagMs after its frame: after frame floor(lag / FRAME) or one frame later, independently for every flap.
      // Not flapping now leaves the next chance to the next frame shown (one short step on, as no decision is asked there)
      // and to every frame after it; after a flap the next frame comes only one engine time later
      var xL = lag / FRAME, dA = lag > 0 ? Math.max(1, DECA / FRAME) : 1, dU = lag > 0 ? Math.max(1, DECU / FRAME) : 1;
      var f0 = Math.min(20, Math.floor(xL)), g, rr, mp;
      jit = lag > 0; gapA = Math.max(1, Math.floor(dA + 0.2));
      for (k = 1; k < 400; k++) {
        g = Math.floor(xL + k * dU); if (g >= H) break;
        // far flaps are replanned many times before they land: thin them out
        if (g > f0 && (dU >= 2 || g <= 36 || (g <= 60 ? g % 2 === 0 : g % 3 === 0))) slot[g] = true;
      }
      rr = roots(f0); mp = rr[4];
      sF = score(Math.min(mp, rr[0]), Math.min(mp, rr[1]));
      sW = score(Math.min(mp, rr[2]), Math.min(mp, rr[3]));
      // tie-break: the same ratings without the frames both choices share
      pF = score(rr[0], rr[1]); pW = score(rr[2], rr[3]);
      // a certain crash: no way through even if every later flap could land on any frame
      dieF = sF < -200; dieW = sW < -200;
      if (dieF || dieW) {
        slot = [];
        for (j = 1; j < H_ANY; j++) slot[j] = j <= 10 || (j <= 30 ? j % 2 === 0 : j % 3 === 0);
        jit = false; gapA = 1; hz = H_ANY; budget = BUDGET_ANY; enough = -200; memoV = {}; memoT = {};
        rr = roots(lag > 0 ? Math.min(20, Math.round(lag / FRAME)) : 0);
        dieF = dieF && Math.min(rr[4], rr[0]) < -200; dieW = dieW && Math.min(rr[4], rr[2]) < -200;
      }
    } catch (err) { sF = 0; sW = 0; pF = 0; pW = 0; dieF = false; dieW = false; }
  }

  var b0 = boxOf(v0), cy0 = top + OFF, bt0 = cy0 - b0[1], bb0 = cy0 + b0[1];
  var rF = Math.round(sF), rW = Math.round(sW), dl = pF - pW;
  var effect = screen !== 1 ? 'same' : (rF > rW ? 'moreRoom' : (rF < rW ? 'lessRoom' : (dl > 0.5 ? 'moreRoom' : (dl < -0.5 ? 'lessRoom' : 'same'))));
  memory.lastNow = now; memory.lastV = v0; memory.lastTop = top; memory.lastScreen = screen;
  // the same test as askWhen: the engine is asked (and flaps) only on these frames
  memory.lastAsk = screen !== 1 || effect === 'moreRoom';
  return {
    over: screen === 2,
    playing: screen === 1,
    birdY: Math.round(cy0),
    vel: Math.round(v0 * 10) / 10,
    roomToGround: Math.round(ground - cy0 - b0[0]),
    pipeDx: lead ? Math.round(lead.x - BR) : null,
    inPipe: lead ? lead.x - PAD < BR : false,
    roomAbove: lead ? Math.round(bt0 - lead.gt) : null,
    roomBelow: lead ? Math.round(lead.gb - bb0) : null,
    msToPipe: lead ? Math.round(Math.max(0, lead.x - PAD - BR) / speed) : null,
    msToClear: lead ? Math.round(Math.max(0, lead.x + lead.w - PAD - BL) / speed) : null,
    nextGapShift: lead && sec ? Math.round((sec.gt + sec.gb - lead.gt - lead.gb) / 2) : null,
    marginIfFlap: rF,
    marginIfWait: rW,
    flapEffect: effect,
    crashIfFlap: screen === 1 && dieF,
    crashIfWait: screen === 1 && dieW,
    unknownThing: unk ? { kind: String(unk.kind).slice(0, 16), dx: Math.round(unk.x - BR), y: Math.round(unk.y), w: Math.round(unk.w), h: Math.round(unk.h), count: unkN } : null
  };
}

teacher:
function teach(state) {
  if (!state || state.over) return 'wait';
  if (!state.playing) return 'flap';
  return state.flapEffect === 'moreRoom' ? 'flap' : 'wait';
}
